local function importedPokemon(quad,model,x,z,r)
 local points={}
 for i,p in ipairs(model.vertices)do points[i]={x+p[1]*r,.075+p[2]*r,z+p[3]*r}end
 for _,f in ipairs(model.faces)do
  quad(points[f[1]],points[f[2]],points[f[3]],points[f[4]],model.colors[f[5]],f[6])
 end
end
function R.build(h,setup)
 local box,quad=h.box,h.quad
 local function rect(x,z,w,d,y,c)
  quad({x-w/2,y,z-d/2},{x+w/2,y,z-d/2},{x+w/2,y,z+d/2},{x-w/2,y,z+d/2},c)
 end
 local function clear(x,z,w,d)
  for _,p in pairs(setup.trainers)do
   if math.abs(p[1]-x)<w/2+8 and math.abs(p[3]-z)<d/2+8 then return false end
  end
  for _,p in pairs(setup.actors)do
   if math.abs(p[1]-x)<w/2+11 and math.abs(p[3]-z)<d/2+10 then return false end
  end
  return true
 end
 local function disk(x,y,z,r,c,N)
  N=N or 16
  for i=0,N-1 do local a,b=i*2*math.pi/N,(i+1)*2*math.pi/N
   quad({x,y,z},{x+math.cos(a)*r,y,z+math.sin(a)*r},{x+math.cos(b)*r,y,z+math.sin(b)*r},{x,y,z},c)
  end
 end
 local steel={.51,.55,.54}
 local silver={.66,.69,.66}
 local green={.40,.55,.47}
 local darkGreen={.24,.36,.31}
 local beige={.52,.50,.40}
 local yellow={.77,.60,.25}
 local cyan={.25,.78,.79}
 local blue={.24,.43,.61}
 local red={.66,.24,.23}
 local function cylinder(x,y,z,r,height,c,n)
  n=n or 18
  disk(x,y+height,z,r,c,n)
  for i=0,n-1 do local a,b=i*2*math.pi/n,(i+1)*2*math.pi/n
   quad({x+r*math.cos(a),y,z+r*math.sin(a)},{x+r*math.cos(b),y,z+r*math.sin(b)},
    {x+r*math.cos(b),y+height,z+r*math.sin(b)},{x+r*math.cos(a),y+height,z+r*math.sin(a)},c,.8+.14*math.cos(a))
  end
 end
 -- A tube between arbitrary endpoints, used for compact pipes and hoses.
 local function pipe(a,b,r,c,n)
  n=n or 10
  local dx,dy,dz=b[1]-a[1],b[2]-a[2],b[3]-a[3];local l=math.sqrt(dx*dx+dy*dy+dz*dz)
  if l<.001 then return end
  dx,dy,dz=dx/l,dy/l,dz/l
  local ux,uy,uz=-dz,0,dx
  if math.abs(dy)>.95 then ux,uy,uz=1,0,0 end
  local ul=math.sqrt(ux*ux+uy*uy+uz*uz);ux,uy,uz=ux/ul,uy/ul,uz/ul
  local vx,vy,vz=dy*uz-dz*uy,dz*ux-dx*uz,dx*uy-dy*ux
  local function p(base,t)return{base[1]+r*(ux*math.cos(t)+vx*math.sin(t)),base[2]+r*(uy*math.cos(t)+vy*math.sin(t)),base[3]+r*(uz*math.cos(t)+vz*math.sin(t))}end
  for i=0,n-1 do local t,s=i*2*math.pi/n,(i+1)*2*math.pi/n
   quad(p(a,t),p(b,t),p(b,s),p(a,s),c,.8+.13*math.cos(t))
   quad(a,p(a,s),p(a,t),a,c,.78);quad(b,p(b,t),p(b,s),b,c,.91)
  end
 end
 local function cable(points,r,c)
  for i=1,#points-1 do pipe(points[i],points[i+1],r,c)end
 end
 local function frontDisk(x,y,z,r,c,n)
  n=n or 20
  for i=0,n-1 do local a,b=i*2*math.pi/n,(i+1)*2*math.pi/n
   quad({x,y,z},{x+r*math.cos(a),y+r*math.sin(a),z},{x+r*math.cos(b),y+r*math.sin(b),z},{x,y,z},c)
  end
 end
 -- Tiled concrete around a broad metal maintenance floor.
 disk(0,.02,0,73.5,{.40,.41,.36},96)
 for x=-66,66,9 do for z=-66,66,9 do
  if (math.abs(x)+4.4)^2+(math.abs(z)+4.4)^2<73^2 then
   local c=({{.48,.47,.39},{.52,.50,.42},{.46,.47,.40},{.55,.52,.43}})[(math.floor(x/9)+math.floor(z/9)*3+200)%4+1]
   rect(x,z,8.8,8.8,.034,c)
  end
 end end
 rect(0,6,51,116,.042,steel)
 rect(0,-2,74,38,.044,steel)
 -- Diamond-plate marks are surface geometry, not a separate texture.
 for x=-33,33,3 do for z=-48,60,4 do
  if math.abs(x)<24 or math.abs(z+2)<18 then
   local flip=(math.floor(x/3)+math.floor(z/4)+100)%2==0 and 1 or -1
   quad({x-.25*flip-.14,.049,z-.65},{x-.25*flip+.14,.049,z-.65},{x+.25*flip+.14,.049,z+.65},{x+.25*flip-.14,.049,z+.65},{.62,.65,.62})
  end
 end end
 -- Drainage channels and steel joins run along the maintenance strip.
 for _,x in ipairs({-29,29})do
  rect(x,6,4.4,109,.051,black)
  for z=-46,58,2.5 do rect(x,z,4.1,.43,.053,{.32,.37,.35})end
  for _,dx in ipairs({-1,1})do rect(x+dx,6,.2,108,.055,steel)end
 end
 for _,z in ipairs({-23,18})do
  rect(0,z,86,2,.056,{.46,.30,.19})
  for x=-40,40,8 do disk(x,.058,z,.45,{.31,.25,.19},8)end
 end
 -- Concrete rear wall, rivets, conduit, electrical junction boxes.
 box(0,0,-64,64,23,2,{.60,.63,.60})
 for x=-30,30,10 do
  box(x,0,-62.88,.14,22,.14,{.43,.47,.44})
  for y=3,21,6 do frontDisk(x+1.5,y,-62.7,.38,{.43,.47,.44},8)end
 end
 for y=6,22,8 do box(0,y,-62.83,63,.13,.14,{.43,.47,.44})end
 for _,x in ipairs({-24,24})do
  box(x,15,-62.6,6.5,5.4,.7,steel)
  box(x,18.1,-62.13,4.5,.7,.15,silver)
 end
 cable({{-24,15,-62},{-24,12,-61},{-16,10,-60},{-16,7,-57}},.45,black)
 cable({{24,15,-62},{24,12,-61},{16,10,-60},{16,7,-57}},.45,black)
 -- Central control bank with separate meters, toggles and coloured indicator discs.
 box(0,0,-57,36,1.3,9,black)
 box(0,1.3,-57,34,15.3,7,darkGreen)
 box(0,16.6,-57,36,1.3,8,green)
 for _,x in ipairs({-11,0,11})do
  box(x,3,-53.38,9.5,12.1,.3,green)
  box(x,9.9,-53.13,6.8,3.7,.2,black)
  box(x,10.3,-52.98,5.9,2.8,.1,{.39,.55,.49})
  for i=0,3 do box(x-2+i*1.3,10.6,-52.86,.6,.8+(i%2)*.6,.1,{.61,.72,.63})end
  for i=0,2 do
   frontDisk(x-2.5+i*2.5,7.8,-53.1,.52,({yellow,red,cyan})[i+1],10)
   box(x-2.5+i*2.5,4.7,-53.1,1.25,1.4,.2,black)
   box(x-2.5+i*2.5,5.0,-52.9,.4,.75,.15,silver)
  end
 end
 box(0,0,-48.7,39,.6,6,steel)
 for _,x in ipairs({-13,13})do rect(x,-48.7,10,1.6,.63,cyan)end
 -- Two compact turbine generators at the rear sides.
 local function generator(x,z)
  box(x,0,z,17,1.2,20,steel)
  box(x,1.2,z,15,11.5,18,green)
  box(x,12.7,z-1.5,13,3.5,13,{.48,.62,.54})
  box(x,16.2,z-1.5,11,.5,10,black)
  for dz=-5,2,1 do box(x,16.72,z+dz,9,.15,.3,steel)end
  frontDisk(x,7.7,z+9.15,5.5,steel,24)
  frontDisk(x,7.7,z+9.19,4.6,black,24)
  for i=0,7 do local a=i*math.pi/4
   local function p(r,t)return{x+r*math.cos(t),7.7+r*math.sin(t),z+9.23}end
   quad(p(1.2,a),p(4,a+.24),p(4,a+.61),p(1.2,a+.5),silver,.85)
  end
  frontDisk(x,7.7,z+9.28,1.4,green,18)
  for _,dx in ipairs({-6.4,6.4})do for y=3,11,4 do frontDisk(x+dx,y,z+9.15,.32,steel,8)end end
  pipe({x-3,16.9,z-2},{x-3,19.5,z-2},1.3,steel,12)
  pipe({x-3,19.5,z-2},{x+2,19.5,z-2},1.3,steel,12)
 end
 generator(-47,-29);generator(47,-29)
 -- Thick cables stay along the back and sides, leaving the top of the arena open.
 for _,s in ipairs({-1,1})do
  cable({{s*46,15,-34},{s*44,21,-40},{s*34,22,-48},{s*18,21,-56},{s*8,19,-58}},1.7,black)
  cable({{s*51,13,-31},{s*56,10,-27},{s*62,4,-14},{s*63,1.2,5}},.9,{.26,.30,.28})
  cable({{s*43,3,-37},{s*36,2,-47},{s*22,2,-49}},.48,yellow)
 end
 -- Weathered red and blue barrels, upright or on their sides.
 local function barrel(x,z,c)
  if not clear(x,z,7,7)then return end
  cylinder(x,.04,z,3.2,7.7,c,16)
  for _,y in ipairs({.3,3.7,7.3})do cylinder(x,y,z,3.3,.35,{.35,.40,.40},16)end
  disk(x,7.76,z,2.85,c,16)
  disk(x-1,7.8,z+.8,.38,steel,8);disk(x+1.2,7.8,z-.7,.29,steel,8)
 end
 for _,p in ipairs({{-57,27,1},{-60,35,2},{-54,44,1},{57,22,2},{60,30,1},{54,48,2},{-25,-56,2},{25,-56,1}})do
  barrel(p[1],p[2],p[3]==1 and red or blue)
 end
 pipe({-54,3.1,52},{-47,3.1,52},3.0,blue,16)
 pipe({-54.2,3.1,52},{-53.8,3.1,52},3.12,steel,16)
 pipe({-47.2,3.1,52},{-46.8,3.1,52},3.12,steel,16)
 -- Small rubble pockets evoke the abandoned FRLG/pixel-art rooms.
 for _,p in ipairs({{-62,-4},{62,7},{-34,52},{32,53},{-33,-53},{33,-53}})do
  local x,z=p[1],p[2]
  for i=0,3 do local px,pz=x+(i%2)*2.1,z+math.floor(i/2)*2.1
   if clear(px,pz,3,3)then
    box(px,.04,pz,2.0+(i%2),1+(i%3)*.45,2.1,({{.45,.46,.41},{.55,.54,.45}})[i%2+1])
   end
  end
 end
 -- Decorative imported Pokemon; separate from the host battle participants.
 importedPokemon(quad,MODEL_VOLTORB,-40,31,6.0)
 importedPokemon(quad,MODEL_ELECTRODE,40,37,7.5)
 -- Plain entrance plate. The host retains its original button, with no badge.
 rect(0,65,16,7,.059,black)
 for z=62.5,67.5,2.5 do rect(0,z,14,1.8,.062,steel)end
end
return R
